// ─── File: StreamsDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.streams;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.math.BigDecimal;

public class StreamsDemo {

    public static void main(String[] args) {
        // Capture the ORIGINAL streams so we can restore them later.
        PrintStream originalOut = System.out;
        PrintStream originalErr = System.err;

        // Redirect out and err to SEPARATE buffers to prove independence.
        ByteArrayOutputStream outBuf = new ByteArrayOutputStream();
        ByteArrayOutputStream errBuf = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outBuf));   // normal output destination
        System.setErr(new PrintStream(errBuf));   // error output destination

        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));
        TransferService service = new TransferService();
        BatchRunner runner = new BatchRunner(service);

        // Valid transfer → writes to out. Invalid → writes to err.
        runner.process(rajesh, priya, new BigDecimal("50000"));
        runner.process(rajesh, priya, new BigDecimal("5000000")); // too big → failure

        // Restore the real console streams before printing the proof.
        System.setOut(originalOut);
        System.setErr(originalErr);

        // Show that the two destinations received DIFFERENT content.
        System.out.println("=== Captured STDOUT (normal) ===");
        System.out.print(outBuf.toString());
        System.out.println("=== Captured STDERR (errors) ===");
        System.out.print(errBuf.toString());
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in TransferService.java ───
class TransferService {
    // Returns true on success; writes normal line to out, failure line to err.
    boolean transfer(Account from, Account to, BigDecimal amount) {
        if (from.getBalance().compareTo(amount) < 0) {
            // err is traditionally UNBUFFERED so alarms surface immediately.
            System.err.println("FAILURE: " + from.getHolderName()
                    + " cannot send Rs." + amount + " (balance Rs." + from.getBalance() + ")");
            return false;
        }
        from.debit(amount);
        to.credit(amount);
        System.out.println("SUCCESS: Rs." + amount + " " + from.getHolderName()
                + " -> " + to.getHolderName() + " (from balance now Rs." + from.getBalance() + ")");
        return true;
    }
}

// ─── Would be in BatchRunner.java ───
class BatchRunner {
    private final TransferService service;
    BatchRunner(TransferService service) { this.service = service; }

    void process(Account from, Account to, BigDecimal amount) {
        // The runner does not care where out/err point; routing is decided outside.
        service.transfer(from, to, amount);
    }
}
